const normalizeCityText=(value:string)=>value.trim().replace(/\s+[—-]\s+[A-Z]{2}$/,'').toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const cityLabel=(name:string,uf:string)=>`${name} — ${uf}`;
const canonicalizeCity=(value:string,rows:Array<{name:string;uf:string}>)=>{const trimmed=value.trim();if(!trimmed)return null;const normalized=trimmed.toLocaleLowerCase('pt-BR');const exact=rows.find(city=>cityLabel(city.name,city.uf).toLocaleLowerCase('pt-BR')===normalized);if(exact)return cityLabel(exact.name,exact.uf);const sameName=rows.filter(city=>normalizeCityText(city.name)===normalizeCityText(trimmed));return sameName.length===1?cityLabel(sameName[0].name,sameName[0].uf):null};
const citiesEqual=(a:string,b:string)=>normalizeCityText(a)===normalizeCityText(b);
function readiness(c:Candidate,j:Job){const req=j.skills.map((s:string)=>s.toLowerCase()),have=new Set(c.skills.map((s:string)=>s.toLowerCase())),ver=new Set(c.verified.map((s:string)=>s.toLowerCase()));const covered=req.filter(s=>have.has(s)).length;const verified=req.filter(s=>ver.has(s)).length;const shift=c.shifts.includes(j.shift);const salary=c.salary>=j.min&&c.salary<=j.max;const city=citiesEqual(c.city,j.city);const score=Math.min(100,Math.round((covered/Math.max(req.length,1))*55+(verified/Math.max(req.length,1))*20+(shift?7:2)+(city?8:3)+(salary?10:0)));return{score,covered,verified,shift,salary,city,gaps:j.skills.filter(s=>!have.has(s.toLowerCase()))}};
